// TEST LAUNCHER. Sends a REAL WhatsApp message to the number below, along the same
// path production uses: it calls 'Followup | Send To Patient', the only workflow
// that sends. That is on purpose: a demo that does not go through the real path
// proves nothing.
//
// To change anything, change it ONLY up here.

const PHONE    = '+15555550100';                 // the operator. E.164, with +
const NAME     = 'Operator';                     // the template's {{1}}
const TEMPLATE = 'followup_20_days_opt1';        // UTILITY: free inside the customer service window
const MILESTONE = '20';

// ---------------------------------------------------------------------------
// Guard: this launcher cannot be used against a patient.
// patient_id is pinned to 'TEST' and the key carries the TEST_ prefix.
// If anyone ever wants to reuse this workflow for production, they have
// to break this by hand — it cannot happen by accident.
// ---------------------------------------------------------------------------

if (!/^\+[1-9]\d{7,14}$/.test(PHONE)) {
  throw new Error(`The test phone is not E.164: "${PHONE}"`);
}

// A new key on every run, to the second. That way it never collides with a previous one
// and nothing has to be deleted from the database to test again — deleting a written
// key is the only thing that can break INV-1 from the outside (INV-17).
const stamp = DateTime.now().setZone('America/Costa_Rica').toFormat('yyyy-MM-dd_HHmmss');

return [{ json: {
  unique_key: `TEST_${stamp}`,
  patient_id: 'TEST',
  last_name:  'Test',
  phone:      PHONE,
  milestone:  MILESTONE,
  template:   TEMPLATE,
  params:     [NAME],
}}];
